import{g as a,ae as e,r as n,B as t}from"./chunks/framework.CZ-ntRvv.js";const _=JSON.parse('{"title":"Tailwind Setup","description":"","frontmatter":{},"headers":[],"relativePath":"docs/getting-started/tailwind.md","filePath":"docs/getting-started/tailwind.md","lastUpdated":1790161475000}'),p={name:"docs/getting-started/tailwind.md"};function o(c,s,d,l,i,r){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="tailwind-setup" tabindex="-1">Tailwind Setup <a class="header-anchor" href="#tailwind-setup" aria-label="Permalink to “Tailwind Setup”">​</a></h1><p>frappe-ui comes with a Tailwind CSS v3 preset. It gives your app the same colors, type, spacing and icons as the components. It doesn&#39;t work with Tailwind CSS v4.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_4q1z3w"> preset</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">content</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/tailwind</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">/** </span><span class="s_y1rh3e">@type</span><span class="s_1zp9pn"> {</span><span class="s_1b1qqa">import(&#39;tailwindcss&#39;).Config</span><span class="s_1zp9pn">}</span><span class="s_1th9sy"> */</span></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  presets</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_11933w">preset</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  content</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_fjrnv8">...</span><span class="s_11933w">content</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./index.html</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./src/**/*.{vue,js,ts,jsx,tsx}</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span></code></pre></div><p>The preset turns on dark mode with <code>data-theme=&quot;dark&quot;</code>, and adds the forms, typography and Lucide icon plugins.</p><h2 id="what-the-preset-replaces" tabindex="-1">What the preset replaces <a class="header-anchor" href="#what-the-preset-replaces" aria-label="Permalink to “What the preset replaces”">​</a></h2><p>Five parts of the theme are replaced, not extended. Classes from the stock Tailwind versions of these compile to nothing, with no error.</p><table tabindex="0"><thead><tr><th>Section</th><th>You get</th><th>You lose</th></tr></thead><tbody><tr><td><code>colors</code></td><td>frappe-ui colors: <code>ink-*</code>, <code>surface-*</code>, <code>outline-*</code></td><td>Tailwind&#39;s palette: <code>slate</code>, <code>sky</code>, …</td></tr><tr><td><code>fontSize</code></td><td>frappe-ui&#39;s type scale, with the same names</td><td>Tailwind&#39;s sizes and line heights</td></tr><tr><td><code>screens</code></td><td><code>sm</code> 640px, <code>md</code> 768px, <code>lg</code> 1024px, <code>xl</code> 1280px</td><td><code>2xl:</code></td></tr><tr><td><code>borderRadius</code></td><td>A numbered scale: <code>rounded-4</code>, <code>rounded-9</code>, …</td><td><code>rounded-sm</code> to <code>rounded-3xl</code></td></tr><tr><td><code>boxShadow</code></td><td>Elevation: <code>shadow-sm</code> to <code>shadow-2xl</code></td><td><code>shadow-inner</code></td></tr></tbody></table><p>Everything else, like spacing and text color, is extended. Tailwind&#39;s own values still work.</p><h2 id="spacing" tabindex="-1">Spacing <a class="header-anchor" href="#spacing" aria-label="Permalink to “Spacing”">​</a></h2><p>Every whole step from <code>1</code> to <code>128</code>, and every half step from <code>0.5</code> to <code>19.5</code>, at <code>0.25rem</code> each. Stock Tailwind skips some numbers above <code>12</code>, such as <code>13</code>, <code>15</code> and <code>17</code>. Here <code>h-17</code> works.</p><p>Widths, heights and sizes use the same scale, so <code>w-17</code>, <code>min-w-40</code>, <code>max-h-52</code> and <code>size-3.5</code> all work. So do the list spacing classes, like <code>list-gap-3</code>.</p><h2 id="content-paths" tabindex="-1">Content paths <a class="header-anchor" href="#content-paths" aria-label="Permalink to “Content paths”">​</a></h2><p>Tailwind only generates the classes it finds in the files you list in <code>content</code>. frappe-ui&#39;s classes are in its own files, so they need to be in that list too.</p><p>Tailwind v3 ignores <code>content</code> inside a preset, so frappe-ui exports its paths for you to spread in:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_euu481">content</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_fjrnv8">...</span><span class="s_11933w">content</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./index.html</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">./src/**/*.{vue,js,ts,jsx,tsx}</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span></span></code></pre></div><p>Leave this out and frappe-ui&#39;s components render without styles.</p><p>The paths point to wherever frappe-ui is installed, so they work in a monorepo or a linked checkout too. When a new version adds folders, updating frappe-ui picks them up. You don&#39;t need to edit your config.</p><h2 id="hover-styles" tabindex="-1">Hover styles <a class="header-anchor" href="#hover-styles" aria-label="Permalink to “Hover styles”">​</a></h2><p><code>hover:</code> styles apply only on devices with a mouse or trackpad. Otherwise a phone would keep a button in its hover state after a tap.</p><p>Anything that appears only on hover needs another way in on touch screens. Show it on devices that can&#39;t hover:</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">button</span></span>
<span class="line"><span class="s_1i4ay4">  class</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">opacity-0 group-hover:opacity-100 [@media(hover:none)]:opacity-100</span><span class="s_w1p9wo">&quot;</span></span>
<span class="line"><span class="s_1zd9e2">&gt;&lt;/</span><span class="s_1uuh8p">button</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Don&#39;t use a breakpoint for this. <code>sm:opacity-0</code> hides the control on a tablet and shows it in a narrow desktop window, which is the opposite of what you want.</p><h2 id="design-tokens" tabindex="-1">Design tokens <a class="header-anchor" href="#design-tokens" aria-label="Permalink to “Design tokens”">​</a></h2><p><code>frappe-ui/tailwind/tokens</code> exports the design tokens as plain data. Use it where Tailwind isn&#39;t available, such as a script, a design tool or a style picker. Colors are <code>oklch(...)</code> strings, radii are px strings, and weights are numbers.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">semanticColors</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/tailwind/tokens</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> backgroundOptions</span><span class="s_2ekfrt"> =</span><span class="s_22m8k2"> Object</span><span class="s_1jjt6x">.</span><span class="s_indoxt">entries</span><span class="s_13ahmt">(</span><span class="s_22m8k2">semanticColors</span><span class="s_1jjt6x">.</span><span class="s_22m8k2">light</span><span class="s_1jjt6x">.</span><span class="s_11933w">surface</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">.</span><span class="s_indoxt">map</span><span class="s_13ahmt">(</span></span>
<span class="line"><span class="s_13ahmt">  (</span><span class="s_1jjt6x">[</span><span class="s_fsg3al">name</span><span class="s_1jjt6x">,</span><span class="s_fsg3al"> value</span><span class="s_1jjt6x">]</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span></span>
<span class="line"><span class="s_r4oegk">    label</span><span class="s_1jjt6x">:</span><span class="s_22m8k2"> name</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">    value</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> \`</span><span class="s_2575z4">var(--surface-</span><span class="s_20l85h">\${</span><span class="s_22m8k2">name</span><span class="s_20l85h">}</span><span class="s_2575z4">, </span><span class="s_20l85h">\${</span><span class="s_22m8k2">value</span><span class="s_20l85h">}</span><span class="s_2575z4">)</span><span class="s_w1p9wo">\`</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  })</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_1th9sy">// [</span></span>
<span class="line"><span class="s_1th9sy">//   { label: &#39;base&#39;, value: &#39;var(--surface-base, oklch(1 0 0))&#39; },</span></span>
<span class="line"><span class="s_1th9sy">//   { label: &#39;gray-1&#39;, value: &#39;var(--surface-gray-1, oklch(0.979 0 0))&#39; },</span></span>
<span class="line"><span class="s_1th9sy">//   …</span></span>
<span class="line"><span class="s_1th9sy">// ]</span></span></code></pre></div><p>Pointing each value at its CSS variable lets it change with the theme, and fall back to the light value outside a frappe-ui page.</p><table tabindex="0"><thead><tr><th>Export</th><th>What it has</th></tr></thead><tbody><tr><td><code>colors</code></td><td>The color ramps, by theme: <code>colors.light.gray[500]</code></td></tr><tr><td><code>semanticColors</code></td><td><code>surface</code>, <code>ink</code>, <code>outline</code> and their alpha versions, by theme: <code>light</code> and <code>dark</code></td></tr><tr><td><code>cssVariables</code></td><td>Every token as a CSS variable. <code>light</code> goes on <code>:root</code>, <code>dark</code> on <code>[data-theme=&quot;dark&quot;]</code></td></tr><tr><td><code>radius</code></td><td>px values for <code>0</code> to <code>9</code>, <code>none</code> and <code>full</code></td></tr><tr><td><code>shadows</code></td><td><code>box-shadow</code> values, named like the <code>shadow-*</code> classes</td></tr><tr><td><code>focusRing</code></td><td>The focus outline, by theme: <code>&#39;2px solid #c9c9c9e5&#39;</code></td></tr><tr><td><code>fontSize</code></td><td>Each size as <code>{ fontSize, lineHeight, letterSpacing, fontWeight }</code></td></tr><tr><td><code>fontWeight</code></td><td>Weights as numbers. <code>regular</code> is 420, not 400</td></tr><tr><td><code>fontFamily</code></td><td><code>{ text: &#39;Inter Variable&#39; }</code></td></tr><tr><td><code>tracking</code></td><td>Letter spacing per size and weight</td></tr><tr><td><code>spacing</code></td><td>The spacing scale, in rem</td></tr><tr><td><code>screens</code></td><td>The four breakpoints</td></tr></tbody></table><p>Every key is typed, so your editor suggests the real names and a typo doesn&#39;t compile. The <code>TextStyle</code> type describes one <code>fontSize</code> entry:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_50ecpt"> type</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">TextStyle</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/tailwind/tokens</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><p>Until 2.0, token names are only added, never renamed or removed.</p><h2 id="updating-the-tokens" tabindex="-1">Updating the tokens <a class="header-anchor" href="#updating-the-tokens" aria-label="Permalink to “Updating the tokens”">​</a></h2><p>This section is for frappe-ui maintainers. The tokens come from Figma and live in <code>tailwind/tokens/*.js</code>. To update them, put a Figma export in <code>.figma-export/</code> and run <code>yarn sync-tokens</code>. It rewrites the token files and their types, and records which export it used in <code>tailwind/tokens/provenance.json</code>.</p><p>Any value where frappe-ui differs from Figma is set in <code>tailwind/tokens/build.js</code>. If you only add or rename a key by hand, run <code>yarn sync-token-types</code> to update the types.</p>`,33)])])}const u=a(p,[["render",o]]);export{_ as __pageData,u as default};
